e[bit.band(bit.bxor(crc, dataBuf[si]), 0xFF) + 1]     end     return crc end local function decodeJsonToTable(cmd)     local tb     if JSON == nil then         JSON = require "cjson"     end     tb = JSON.decode(cmd)     return tb end local function encodeTableToJson(luaTable)     local jsonStr     if JSON == nil then         JSON = require "cjson"     end     jsonStr = JSON.encode(luaTable)     return jsonStr end local function string2table(hexstr)     local tb = {}     local i = 1     local j = 1     for i = 1, #hexstr - 1, 2 do         local doublebytestr = string.sub(hexstr, i, i + 1)         tb[j] = tonumber(doublebytestr, 16)         j = j + 1     end     return tb end local function table2string(cmd)     local ret = ""     local i     for i = 1, #cmd do         ret = ret .. string.char(cmd[i])     end     return ret end local function string2hexstring(str)     local ret = ""     for i = 1, #str do         ret = ret .. string.format("%02x", str:byte(i))     end     return ret end local function checkBoundary(data, min, max)     if (not data) then         data = 0     end     data = tonumber(data)     if ((data >= min) and (data <= max)) then         return data     else         if (data < min) then             return min         else             return max         end     end end local function string2Int(data)     if (not data) then         data = tonumber("0")     end     data = tonumber(data)     if (data == nil) then         data = 0     end     return data end local function int2String(data)     if (not data) then         data = tostring(0)     end     data = tostring(data)     if (data == nil) then         data = "0"     end     return data end local function print_lua_table(lua_table, indent)     indent = indent or 0     for k, v in pairs(lua_table) do         if type(k) == "string" then             k = string.format("%q", k)         end         local szSuffix = ""         if type(v) == "table" then             szSuffix = "{"         end         local szPrefix = string.rep("    ", indent)         formatting = szPrefix .. "[" .. k .. "]" .. " = " .. szSuffix         if type(v) == "table" then             print(formatting)             print_lua_table(v, indent + 1)             print(szPrefix .. "},")         else             local szValue = ""             if type(v) == "string" then                 szValue = string.format("%q", v)             else                 szValue = tostring(v)             end             print(formatting .. szValue .. ",")         end     end end local function valueTableInitialization() 	valuetable["SOFTWARE_VERSION"] = 0xFF 	valuetable["CURTAIN_STATUS"] = 0xFF 	valuetable["CURTAIN_POSITION"] = 0xFF 	valuetable["CURTAIN_DIRECTION"] = 0xFF 	valuetable["ERROR_CODE"] = 0xFF end local function updateGlobalPropertyValueByJson(luaTable) 	 	valueTableInitialization() 	 	if(luaTable[keytable["KEY_SUB_PACKET_TYPE"]] == nil  	or luaTable[keytable["KEY_SUB_PACKET_TYPE"]] == ""  	or luaTable[keytable["KEY_SUB_PACKET_TYPE"]] ==  VALUE_FUNCTION_SETTING 	or luaTable[keytable["KEY_SUB_PACKET_TYPE"]] ==  VALUE_FUNCTION_QUERY) then 		cmdType = 0x01	 	end 	 	valuetable["SOFTWARE_VERSION"] = string2Int(luaTable[keytable["KEY_SOTFWARE_VERSION"]]) 	 	if(luaTable[keytable["KEY_CURTAIN_STATUS"]] == VALUE_CLOSE) then 		valuetable["CURTAIN_STATUS"] = 0x00 	elseif(luaTable[keytable["KEY_CURTAIN_STATUS"]] == VALUE_OPEN) then 		valuetable["CURTAIN_STATUS"] = 0x01 	elseif(luaTable[keytable["KEY_CURTAIN_STATUS"]] == VALUE_STOP) then 		valuetable["CURTAIN_STATUS"] = 0x02 	end 	 	if(luaTable[keytable["KEY_CURTAIN_POSITION"]] ~= nil) then  	valuetable["CURTAIN_POSITION"] = string2Int(luaTable[keytable["KEY_CURTAIN_POSITION"]]) 	end 	 	if(luaTable[keytable["KEY_CURTAIN_DIRECTION"]] == VALUE_POSITIVE) then 		valuetable["CURTAIN_DIRECTION"] = 0x00 	elseif(luaTable[keytable["KEY_CURTAIN_DIRECTION"]] == VALUE_REVERSE) then 		valuetable["CURTAIN_DIRECTION"] = 0x01 	end 	 	if(luaTable[keytable["KEY_ERROR_CODE"]] ~= nil) then  	valuetable["ERROR_CODE"] = string2Int(luaTable[keytable["KEY_ERROR_CODE"]]) 	end end local function updateGlobalPropertyValueByByte(messageBytes) 	local hard_version_len 	local soft_version_len 	 	 	valueTableInitialization() 	 	if(messageBytes[0] ~= nil) then 	cmdType = messageBytes[0] 	end 	if(cmdType == 0x01) then 		 		if(messageBytes[1] ~= nil) then 		valuetable["SOFTWARE_VERSION"] = messageBytes[1] 		end 		 		if(messageBytes[2] ~= nil) then 		valuetable["CURTAIN_STATUS"] = messageBytes[2] 		end 		 		if(messageBytes[3] ~= nil) then 		valuetable["CURTAIN_POSITION"] = messageBytes[3] 		end 		 		if(messageBytes[4] ~= nil) then 		valuetable["CURTAIN_DIRECTION"] = messageBytes[4] 		end 		 		if(messageBytes[5] ~= nil) then 		valuetable["ERROR_CODE"] = messageBytes[5] 		end 	end end local function assembleJsonByGlobalProperty()     local streams = {}          streams[keytable["KEY_VERSION"]] = VALUE_VERSION 	 	     if(dataType == BYTE_CONTROL_REQUEST) then 		 		if(cmdType == 0x01) then 			streams[keytable["KEY_SUB_PACKET_TYPE"]] = VALUE_FUNCTION_SETTING 		end 	 	elseif (dataType == BYTE_QUERY_REQUEST) then 		 		if(cmdType == 0x01) then 			streams[keytable["KEY_SUB_PACKET_TYPE"]] = VALUE_FUNCTION_QUERY 		end 	 	elseif ((dataType == BYTE_REPORT_NACK) or (dataType == BYTE_REPORT_ACK)) then 		 		if(cmdType == 0x01) then 			streams[keytable["KEY_SUB_PACKET_TYPE"]] = VALUE_FUNCTION_REPORT 		end 	end 	 	if(valuetable["SOFTWARE_VERSION"] ~= 0xFF)then 		streams[keytable["KEY_SOTFWARE_VERSION"]] = int2String(valuetable["SOFTWARE_VERSION"]) 	end 	 	if(valuetable["CURTAIN_STATUS"] == 0x00) then 		streams[keytable["KEY_CURTAIN_STATUS"]] = VALUE_CLOSE 	elseif(valuetable["CURTAIN_STATUS"] == 0x01) then 		streams[keytable["KEY_CURTAIN_STATUS"]] = VALUE_OPEN 	elseif(valuetable["CURTAIN_STATUS"] == 0x02) then 		streams[keytable["KEY_CURTAIN_STATUS"]] = VALUE_STOP 	end 	 	if(valuetable["CURTAIN_POSITION"] ~= 0xFF) then 		streams[keytable["KEY_CURTAIN_POSITION"]] = int2String(valuetable["CUR